const resolveIntegration = async (
	git: IStartupGitSeam,
	branch: string,
): Promise<{ readonly ref: string; readonly sha: string }> => {
	const candidates = [
		`refs/remotes/origin/${branch}`,
		`refs/heads/${branch}`,
		branch,
	];
	for (const candidate of candidates) {
		const sha = await git.resolveRef(candidate);
		if (sha !== undefined) return { ref: candidate, sha };
	}
	return { ref: `refs/heads/${branch}`, sha: '' };

const readRemoteUrl = async (git: IGitRunner): Promise<string | undefined> => {
	const named = await git(['remote']);
	if (!named.ok) return undefined;
	const first = named.output
		.split('\n')
		.map((line) => line.trim())
		.find((line) => line.length > 0);
	if (first === undefined) return undefined;
	const url = await git(['remote', 'get-url', first]);
	return url.ok ? url.output.trim() : undefined;

const release = async (): Promise<void> => {
	await rm(options.path, { force: true });
};

const deadHere =
	held !== undefined &&
	held.machineId === options.machineId &&
	!isAlive(held.pid);
if (age <= ttlMs && !deadHere) {
	return {
		kind: 'busy',
		holder:
			held === undefined
				? 'unknown'
				: `${held.machineId}#${String(held.pid)}`,
	};
}
// Abandoned: take it over, and say who we took it from.
await release();
try {
	await write();
	return { kind: 'acquired', release };

const git = (args: readonly string[], cwd = repoRoot()): string => {
	const result = spawnSync('git', [...args], { cwd, encoding: 'utf8' });
	return result.status === 0 ? result.stdout.trim() : '';
};

if (!dryRun) {
	const restore = plan.release.filter(existsInIntegration);
	const remove = plan.release.filter(
		(path) => !existsInIntegration(path),
	);
	if (restore.length > 0)
		git(['checkout', integration, '--', ...restore]);
	for (const path of remove)
		rmSync(join(repoRoot(), path), { force: true });
}

process.stdout.write(
	`${renderVerdict({
		integration,
		released: plan.release,
		kept: plan.keep,
	})}\n`,
